**File:** `components/shared/app-view/style-compose.ts`

These are pure functions with zero dependencies — ideal unit test targets.

**Untested edge cases:**
- `null`-checking logic (`!= null` vs `=== 0`) — a value of `0` must still be included
- Shorthand vs explicit props (`p` vs `px`/`py` coexistence)
- `center` prop sets both `alignItems` and `justifyContent`

```ts
// tests/style-compose.test.ts
import { composeSpacing, composeFlexbox, composeRounding, composeBorder } from
  '@/components/shared/app-view/style-compose';

describe('composeSpacing', () => {
  it('maps p to padding', () => {
    expect(composeSpacing({ p: 16 })).toEqual({ padding: 16 });
  });

  it('includes zero values (does not skip p=0)', () => {
    expect(composeSpacing({ p: 0 })).toHaveProperty('padding', 0);
  });

  it('maps all shorthand props', () => {
    const result = composeSpacing({ px: 8, py: 4 });
    expect(result).toMatchObject({ paddingHorizontal: 8, paddingVertical: 4 });
  });

  it('maps margin props', () => {
    expect(composeSpacing({ m: 12, mt: 4 })).toMatchObject({ margin: 12, marginTop: 4 });
  });

  it('returns empty object for no props', () => {
    expect(composeSpacing({})).toEqual({});
  });

  it('maps gap, rowGap, columnGap', () => {
    expect(composeSpacing({ gap: 8, rowGap: 4, columnGap: 2 })).toMatchObject({
      gap: 8, rowGap: 4, columnGap: 2,
    });
  });
});

describe('composeFlexbox', () => {
  it('sets flexDirection row', () => {
    expect(composeFlexbox({ row: true })).toHaveProperty('flexDirection', 'row');
  });

  it('center sets both alignItems and justifyContent', () => {
    const result = composeFlexbox({ center: true });
    expect(result).toMatchObject({ alignItems: 'center', justifyContent: 'center' });
  });

  it('align overrides center alignItems', () => {
    const result = composeFlexbox({ center: true, align: 'flex-start' });
    expect(result.alignItems).toBe('flex-start');
  });

  it('flex=0 is included (not skipped)', () => {
    expect(composeFlexbox({ flex: 0 })).toHaveProperty('flex', 0);
  });

  it('returns empty object for no props', () => {
    expect(composeFlexbox({})).toEqual({});
  });
});

describe('composeRounding', () => {
  it('rounded maps to borderRadius', () => {
    expect(composeRounding({ rounded: 8 })).toHaveProperty('borderRadius', 8);
  });

  it('roundedTop sets both top corners', () => {
    expect(composeRounding({ roundedTop: 12 })).toMatchObject({
      borderTopLeftRadius: 12,
      borderTopRightRadius: 12,
    });
  });

  it('roundedBottom sets both bottom corners', () => {
    expect(composeRounding({ roundedBottom: 6 })).toMatchObject({
      borderBottomLeftRadius: 6,
      borderBottomRightRadius: 6,
    });
  });

  it('roundedLeft sets left corners', () => {
    expect(composeRounding({ roundedLeft: 4 })).toMatchObject({
      borderTopLeftRadius: 4,
      borderBottomLeftRadius: 4,
    });
  });
});

describe('composeBorder', () => {
  it('maps borderWidth', () => {
    expect(composeBorder({ borderWidth: 1 })).toHaveProperty('borderWidth', 1);
  });

  it('maps borderColor', () => {
    expect(composeBorder({ borderColor: '#fff' })).toHaveProperty('borderColor', '#fff');
  });

  it('returns empty object when no props', () => {
    expect(composeBorder({})).toEqual({});
  });
});
```

