**File:** `components/shared/app-view/safe-area.ts`

**Untested edge cases:**
- `mode=false` returns empty object
- `mode=true` resolves to `'all'`
- `safeTop` only applies on iOS (platform branching)
- Existing spacing not overwritten when inset is smaller

```ts
// tests/safe-area.test.ts
import { Platform } from 'react-native';
import { composeSafeAreaPadding } from '@/components/shared/app-view/safe-area';

const insets = { top: 44, bottom: 34, left: 0, right: 0 };

describe('composeSafeAreaPadding', () => {
  it('returns empty for mode=false', () => {
    expect(composeSafeAreaPadding({ mode: false, insets, spacing: {} })).toEqual({});
  });

  it('mode=true applies all four sides', () => {
    const result = composeSafeAreaPadding({ mode: true, insets, spacing: {} });
    expect(result.paddingTop).toBe(44);
    expect(result.paddingBottom).toBe(34);
  });

  it('mode="top" only applies paddingTop', () => {
    const result = composeSafeAreaPadding({ mode: 'top', insets, spacing: {} });
    expect(result.paddingTop).toBe(44);
    expect(result.paddingBottom).toBeUndefined();
  });

  it('mode="bottom" only applies paddingBottom', () => {
    const result = composeSafeAreaPadding({ mode: 'bottom', insets, spacing: {} });
    expect(result.paddingBottom).toBe(34);
    expect(result.paddingTop).toBeUndefined();
  });

  it('mode="horizontal" applies left and right', () => {
    const insetsH = { top: 44, bottom: 34, left: 20, right: 20 };
    const result = composeSafeAreaPadding({ mode: 'horizontal', insets: insetsH, spacing: {} });
    expect(result.paddingLeft).toBe(20);
    expect(result.paddingRight).toBe(20);
    expect(result.paddingTop).toBeUndefined();
  });

  it('existing spacing not clobbered when larger than inset', () => {
    const result = composeSafeAreaPadding({
      mode: 'top',
      insets: { ...insets, top: 10 },
      spacing: { paddingTop: 50 },
    });
    expect(result.paddingTop).toBe(50); // Math.max(50, 10)
  });

  it('safeTop on iOS uses SAFE_AREA_TOP_FALLBACK', () => {
    (Platform as any).OS = 'ios';
    const result = composeSafeAreaPadding({ mode: false, safeTop: true, insets, spacing: {} });
    expect(result.paddingTop).toBeGreaterThan(0);
    (Platform as any).OS = 'ios'; // reset
  });

  it('safeTop ignored on android', () => {
    (Platform as any).OS = 'android';
    const result = composeSafeAreaPadding({ mode: false, safeTop: true, insets, spacing: {} });
    expect(result.paddingTop).toBeUndefined();
    (Platform as any).OS = 'ios';
  });
});
