**File:** `components/shared/app-button/colors.ts`

**Untested edge cases:**
- `default` case in `kindTint` (unknown kind falls back to `primary`)
- All `kind` values for `solidDefaults`

```ts
// tests/button-colors.test.ts
import { kindTint, solidDefaults } from '@/components/shared/app-button/colors';

const tokens = {
  primary: '#1a73e8', primaryBg: '#e8f0fe', onPrimary: '#fff', primaryPressed: '#1557b0',
  secondary: '#aaa', secondaryBg: '#eee', onSecondary: '#000', secondaryPressed: '#888',
  brand: '#f00', brandBg: '#fee', onBrand: '#fff', brandPressed: '#c00',
  success: '#0f0', successPressed: '#0c0',
  error: '#f00', errorPressed: '#c00',
  info: '#00f', infoPressed: '#00c',
  warning: '#ff0', warningPressed: '#cc0',
  text: '#111', textPressed: '#333',
  white: '#fff',
};

describe('kindTint', () => {
  it.each(['primary','secondary','success','error','info','warning','text','brand'])(
    'returns token for kind=%s', (kind) => {
      expect(kindTint(tokens as any, kind as any)).toBeDefined();
    }
  );

  it('falls back to primary for unknown kind', () => {
    expect(kindTint(tokens as any, 'unknown' as any)).toBe(tokens.primary);
  });
});

describe('solidDefaults', () => {
  it('primary returns primaryBg, onPrimary, primaryPressed', () => {
    const r = solidDefaults(tokens as any, 'primary');
    expect(r).toEqual({ bg: tokens.primaryBg, fg: tokens.onPrimary, pressed: tokens.primaryPressed });
  });

  it('brand returns brandBg, onBrand, brandPressed', () => {
    const r = solidDefaults(tokens as any, 'brand');
    expect(r).toEqual({ bg: tokens.brandBg, fg: tokens.onBrand, pressed: tokens.brandPressed });
  });

  it('success returns white fg', () => {
    expect(solidDefaults(tokens as any, 'success').fg).toBe(tokens.white);
  });

  it('returns undefined pressed for unknown kind', () => {
    const r = solidDefaults(tokens as any, 'unknown' as any);
    expect(r.pressed).toBeUndefined();
  });
});
