**File:** `components/shared/app-form/define-form.ts`

**Untested edge cases:**
- Row fields: defaults and schemas extracted from nested children
- Fields without `name` are skipped in `defaultValues`
- `superRefine` is applied to schema
- No schema fields → `schema` is `undefined`

```ts
// tests/define-form.test.ts
import { z } from 'zod';
import { defineForm } from '@/components/shared/app-form/define-form';

describe('defineForm', () => {
  it('extracts defaultValues from flat fields', () => {
    const { defaultValues } = defineForm([
      { name: 'email', type: 'text', defaultValue: 'a@b.com' },
      { name: 'age', type: 'text', defaultValue: 25 },
    ]);
    expect(defaultValues).toEqual({ email: 'a@b.com', age: 25 });
  });

  it('builds zod schema from field schemas', () => {
    const { schema } = defineForm([
      { name: 'email', type: 'text', schema: z.string().email(), defaultValue: '' },
    ]);
    expect(schema).toBeDefined();
    const result = (schema as any).safeParse({ email: 'not-email' });
    expect(result.success).toBe(false);
  });

  it('schema is undefined when no fields have schema', () => {
    const { schema } = defineForm([
      { name: 'name', type: 'text', defaultValue: '' },
    ]);
    expect(schema).toBeUndefined();
  });

  it('strips defaultValue and schema from config fields', () => {
    const { config } = defineForm([
      { name: 'x', type: 'text', schema: z.string(), defaultValue: '' },
    ]);
    expect((config.fields[0] as any).schema).toBeUndefined();
    expect((config.fields[0] as any).defaultValue).toBeUndefined();
  });

  it('extracts defaults from row fields', () => {
    const { defaultValues } = defineForm([
      {
        type: 'row',
        fields: [
          { name: 'first', type: 'text', defaultValue: 'John' },
          { name: 'last',  type: 'text', defaultValue: 'Doe'  },
        ],
      } as any,
    ]);
    expect(defaultValues).toEqual({ first: 'John', last: 'Doe' });
  });

  it('applies superRefine to schema', () => {
    const { schema } = defineForm(
      [
        { name: 'pass', type: 'text', schema: z.string(), defaultValue: '' },
        { name: 'confirm', type: 'text', schema: z.string(), defaultValue: '' },
      ],
      {
        superRefine: (vals, ctx) => {
          if (vals.pass !== vals.confirm) {
            ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['confirm'], message: 'No match' });
          }
        },
      },
    );
    const result = (schema as any).safeParse({ pass: 'abc', confirm: 'xyz' });
    expect(result.success).toBe(false);
    expect(result.error.issues[0].message).toBe('No match');
  });
});
