**File:** `components/shared/app-button/hooks/use-loading-delay.ts`

**Untested edge cases:**
- No delay: `show` immediately true when loading starts
- With delay: `show` stays false until timeout fires
- `loading=false` resets `show` immediately
- Timeout cleared on unmount (no memory leak)

```ts
// tests/use-loading-delay.test.ts
import { renderHook, act } from '@testing-library/react-hooks';
import { useLoadingDelay } from '@/components/shared/app-button/hooks/use-loading-delay';

describe('useLoadingDelay', () => {
  beforeEach(() => jest.useFakeTimers());
  afterEach(() => jest.useRealTimers());

  it('shows immediately when loading=true and no delay', () => {
    const { result } = renderHook(() => useLoadingDelay(true));
    expect(result.current).toBe(true);
  });

  it('does not show immediately when delayMs provided', () => {
    const { result } = renderHook(() => useLoadingDelay(true, 500));
    expect(result.current).toBe(false);
  });

  it('shows after delay elapses', () => {
    const { result } = renderHook(() => useLoadingDelay(true, 300));
    act(() => jest.advanceTimersByTime(300));
    expect(result.current).toBe(true);
  });

  it('resets to false when loading becomes false', () => {
    const { result, rerender } = renderHook(
      ({ loading }) => useLoadingDelay(loading),
      { initialProps: { loading: true } },
    );
    expect(result.current).toBe(true);
    rerender({ loading: false });
    expect(result.current).toBe(false);
  });

  it('clears timeout on unmount', () => {
    const clearSpy = jest.spyOn(global, 'clearTimeout');
    const { unmount } = renderHook(() => useLoadingDelay(true, 1000));
    unmount();
    expect(clearSpy).toHaveBeenCalled();
  });

  it('returns false when loading=false from the start', () => {
    const { result } = renderHook(() => useLoadingDelay(false));
    expect(result.current).toBe(false);
  });
});
