**File:** `components/shared/app-form/presets.ts`

**Untested edge cases:**
- Default values applied correctly (empty string, arrays, objects)
- `multiSelectField` delegates to `selectField` with `multiple: true`
- `selectableCardField` normalizes string icons to `{ family: 'symbol', name: ... }`
- `rowField` default gap is `12`

```ts
// tests/presets.test.ts
import {
  emailField, passwordField, textField, multiSelectField,
  selectField, selectableCardField, rowField, hiddenField,
} from '@/components/shared/app-form/presets';

describe('emailField', () => {
  it('has type text and keyboardType email-address', () => {
    const f = emailField('email');
    expect(f.type).toBe('text');
    expect(f.props?.keyboardType).toBe('email-address');
  });

  it('uses provided label', () => {
    expect(emailField('email', { label: 'Work Email' }).label).toBe('Work Email');
  });

  it('defaults to empty string', () => {
    expect(emailField('email').defaultValue).toBe('');
  });
});

describe('passwordField', () => {
  it('sets secureTextEntry=true', () => {
    expect(passwordField('password').props?.secureTextEntry).toBe(true);
  });

  it('defaults textContentType to newPassword', () => {
    expect(passwordField('password').props?.textContentType).toBe('newPassword');
  });
});

describe('multiSelectField', () => {
  it('sets multiple=true and defaultValue to array', () => {
    const f = multiSelectField('tags', { options: [] });
    expect(f.props?.multiple).toBe(true);
    expect(Array.isArray(f.defaultValue)).toBe(true);
  });
});

describe('selectableCardField', () => {
  it('normalizes string icon to object form', () => {
    const f = selectableCardField('type', {
      options: [{ label: 'Car', value: 'car', icon: 'car-icon' }],
    });
    expect(f.props?.options[0].icon).toEqual({ family: 'symbol', name: 'car-icon' });
  });

  it('passes through object icon unchanged', () => {
    const icon = { family: 'material', name: 'directions-car' };
    const f = selectableCardField('type', {
      options: [{ label: 'Car', value: 'car', icon }],
    });
    expect(f.props?.options[0].icon).toEqual(icon);
  });
});

describe('rowField', () => {
  it('defaults gap to 12', () => {
    const r = rowField([]);
    expect(r.gap).toBe(12);
  });

  it('accepts custom gap', () => {
    expect(rowField([], { gap: 8 }).gap).toBe(8);
  });

  it('has type row', () => {
    expect(rowField([]).type).toBe('row');
  });
});

describe('hiddenField', () => {
  it('has type hidden', () => {
    expect(hiddenField('id').type).toBe('hidden');
  });

  it('stores defaultValue', () => {
    expect(hiddenField('id', { defaultValue: '42' }).defaultValue).toBe('42');
  });
});
