**File:** `components/screens-components/smart-search-bar.tsx`

**Untested scenarios:**
- Renders the search input with default placeholder
- `onPress` called when query changes (onChange mode)
- Voice search button triggers `onVoicePress`
- Image search button triggers `onImageSearchPress`
- Notification button triggers `onNotificationPress`

```tsx
// tests/smart-search-bar.test.tsx
import React from 'react';
import { render, fireEvent } from '@testing-library/react-native';
import { SmartSearchBar } from '@/components/screens-components/smart-search-bar';

// Mock theme context
jest.mock('@/contexts/theme.context', () => ({
  useThemeContext: () => ({ tokens: { text: '#000', onSecondary: '#fff' } }),
}));

describe('SmartSearchBar', () => {
  it('renders with default placeholder', () => {
    const { getByPlaceholderText } = render(<SmartSearchBar />);
    expect(getByPlaceholderText('Smart search...')).toBeTruthy();
  });

  it('renders with custom placeholder', () => {
    const { getByPlaceholderText } = render(<SmartSearchBar placeholder="Find parts..." />);
    expect(getByPlaceholderText('Find parts...')).toBeTruthy();
  });

  it('calls onVoicePress when voice button pressed', () => {
    const onVoicePress = jest.fn();
    const { getByLabelText } = render(<SmartSearchBar onVoicePress={onVoicePress} />);
    fireEvent.press(getByLabelText('Voice search'));
    expect(onVoicePress).toHaveBeenCalled();
  });

  it('calls onImageSearchPress when camera button pressed', () => {
    const onImageSearchPress = jest.fn();
    const { getByLabelText } = render(<SmartSearchBar onImageSearchPress={onImageSearchPress} />);
    fireEvent.press(getByLabelText('Search with photo'));
    expect(onImageSearchPress).toHaveBeenCalled();
  });

  it('calls onNotificationPress when bell pressed', () => {
    const onNotificationPress = jest.fn();
    const { getByLabelText } = render(<SmartSearchBar onNotificationPress={onNotificationPress} />);
    fireEvent.press(getByLabelText('Notifications'));
    expect(onNotificationPress).toHaveBeenCalled();
  });
});
