import { renderHook, act } from '@testing-library/react-hooks';
import { useDebouncedPress } from '@/components/shared/app-button/hooks/use-debounced-press';

jest.mock('@/utils/haptics', () => ({ triggerHaptic: jest.fn() }));
import { triggerHaptic } from '@/utils/haptics';

const fakeEvent = {} as any;

describe('useDebouncedPress', () => {
  beforeEach(() => jest.clearAllMocks());

  it('calls onPress when not disabled or loading', () => {
    const onPress = jest.fn();
    const { result } = renderHook(() => useDebouncedPress({ onPress }));
    act(() => result.current(fakeEvent));
    expect(onPress).toHaveBeenCalledWith(fakeEvent);
  });

  it('does not call onPress when disabled', () => {
    const onPress = jest.fn();
    const { result } = renderHook(() => useDebouncedPress({ onPress, disabled: true }));
    act(() => result.current(fakeEvent));
    expect(onPress).not.toHaveBeenCalled();
  });

  it('does not call onPress when loading', () => {
    const onPress = jest.fn();
    const { result } = renderHook(() => useDebouncedPress({ onPress, loading: true }));
    act(() => result.current(fakeEvent));
    expect(onPress).not.toHaveBeenCalled();
  });

  it('debounces rapid calls within debounceMs window', () => {
    jest.useFakeTimers();
    const onPress = jest.fn();
    const { result } = renderHook(() => useDebouncedPress({ onPress, debounceMs: 500 }));
    act(() => result.current(fakeEvent)); // allowed
    act(() => result.current(fakeEvent)); // blocked — within 500ms
    expect(onPress).toHaveBeenCalledTimes(1);
    jest.useRealTimers();
  });

  it('allows second press after debounce window expires', () => {
    jest.useFakeTimers();
    const onPress = jest.fn();
    const { result } = renderHook(() => useDebouncedPress({ onPress, debounceMs: 300 }));
    act(() => result.current(fakeEvent));
    jest.advanceTimersByTime(400);
    act(() => result.current(fakeEvent));
    expect(onPress).toHaveBeenCalledTimes(2);
    jest.useRealTimers();
  });

  it('calls triggerHaptic on valid press', () => {
    const { result } = renderHook(() => useDebouncedPress({ haptics: 'light', onPress: jest.fn() }));
    act(() => result.current(fakeEvent));
    expect(triggerHaptic).toHaveBeenCalledWith('light');
  });
});

